BEGIN
 IF current_database()<>'club_arena_qualification' OR inet_server_addr() IS NOT NULL
 OR current_user<>'supabase_admin' OR session_user<>'supabase_admin'
 OR NOT EXISTS(SELECT FROM pg_roles WHERE oid=10 AND rolname=current_user AND rolsuper)
 OR EXISTS(SELECT FROM pg_roles WHERE rolname='postgres' AND rolsuper)
 THEN RAISE EXCEPTION 'FIXTURE_ORIGINAL_BOOTSTRAP_REQUIRED'; END IF;
 WITH RECURSIVE seed AS (SELECT oid FROM pg_roles WHERE rolname=ANY(ARRAY['anon','authenticated','authenticator','cli_login_postgres','dashboard_user','pg_create_subscription','pg_monitor','pg_read_all_data','pg_read_all_settings','pg_read_all_stats','pg_signal_backend','pg_stat_scan_tables','pgbouncer','postgres','service_role','supabase_admin','supabase_auth_admin','supabase_backup_admin','supabase_etl_admin','supabase_functions_admin','supabase_privileged_role','supabase_read_only_user','supabase_realtime_admin','supabase_replication_admin','supabase_storage_admin'])),
 reachable(oid) AS (SELECT oid FROM seed UNION SELECT CASE WHEN m.member=r.oid THEN m.roleid ELSE m.member END
 FROM pg_auth_members m JOIN reachable r ON m.member=r.oid OR m.roleid=r.oid),
 scoped AS (SELECT oid,rolname FROM pg_roles WHERE oid IN(SELECT oid FROM reachable))
 SELECT jsonb_agg(jsonb_build_array(a.rolname,b.rolname,
 pg_has_role(a.oid,b.oid,'MEMBER'),pg_has_role(a.oid,b.oid,'USAGE'),pg_has_role(a.oid,b.oid,'SET'))
 ORDER BY a.rolname,b.rolname) INTO actual FROM scoped a CROSS JOIN scoped b;
 IF actual IS DISTINCT FROM expected THEN
 RAISE EXCEPTION 'FIXTURE_ROLE_MEMBERSHIP_MATRIX_REQUIRED'; END IF;
END $membership_matrix$;
ROLLBACK;
